package main

import (
	"fmt"
	"time"
)

// ExpenseRecord represents a record of an expense with metadata.
type ExpenseRecord struct {
	ID          string
	Amount      float64
	Currency    string
	Description string
	Category    string
	Date        time.Time
}

// NewExpenseRecord creates a new ExpenseRecord instance with validation.
// It returns an error if the amount is not positive.
func NewExpenseRecord(id string, amount float64, currency string, description string, category string, date time.Time) (*ExpenseRecord, error) {
	if amount <= 0 {
		return nil, fmt.Errorf("amount must be positive")
	}
	return &ExpenseRecord{
		ID:          id,
		Amount:      amount,
		Currency:    currency,
		Description: description,
		Category:    category,
		Date:        date,
	}, nil
}
